private TreeNode<T> rotateRight(TreeNode<T> node) {
    // If there's no left child, rotation is not possible; return node unchanged.
    if (node == null || node.getLeft() == null) {
        return node;
    }

    // Node's left child becomes the new parent of this subtree.
    TreeNode<T> newParent = node.getLeft();
    TreeNode<T> leftRightSubtree = newParent.getRight();

    // Perform the rotation.
    newParent.setRight(node);
    node.setLeft(leftRightSubtree);

    // Update parent references for node and its new left subtree.
    TreeNode<T> oldParent = node.getParent();
    node.setParent(newParent);
    newParent.setParent(oldParent);

    // If the left-right subtree exists, set its parent to the old node.
    if (leftRightSubtree != null) {
        leftRightSubtree.setParent(node);
    }

    // Update the old parent to point to the new parent instead of the old node.
    if (oldParent != null) {
        if (oldParent.getLeft() == node) {
            oldParent.setLeft(newParent);
        } else if (oldParent.getRight() == node) {
            oldParent.setRight(newParent);
        }
    }

    return newParent;
}

