    for (java.io.File f : files) {
        if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
            try {
                java.net.URL url = f.toURI().toURL();
                if (!cpV.contains(url)) {
                    cpV.add(url);
                }
            } catch (java.net.MalformedURLException e) {
                // ignore malformed URL
            }
        }
    }
}

