public String format(LoggingEvent event){
    // Basic conversion pattern support: %d (date), %p (log level), %m (message), %n (newline)
    String pattern = event.getConversionPattern();
    if (pattern == null) {
        pattern = "%d %-5p %m%n";
    }

    // Prepare values for placeholders
    String timestamp = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss")
            .format(new java.util.Date(event.getTimestamp()));
    String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
    String message = event.getMessage() != null ? event.getMessage() : "";

    // Perform simple placeholder replacement
    String formatted = pattern.replace("%d", timestamp)
                              .replace("%p", level)
                              .replace("%m", message)
                              .replace("%n", System.lineSeparator());

    return formatted;
}

