public String format(LoggingEvent event) {
    // Default conversion pattern; use a field if available
    String pattern = "%d{yyyy-MM-dd HH:mm:ss.SSS} [%t] %-5p %c - %m%n";
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < pattern.length()) {
        char ch = pattern.charAt(i);
        if (ch == '%' && i + 1 < pattern.length()) {
            char spec = pattern.charAt(i + 1);
            switch (spec) {
                case 'd': // date
                    // support optional format in braces
                    int formatStart = i + 2;
                    int formatEnd = formatStart;
                    if (i + 2 < pattern.length() && pattern.charAt(i + 2) == '{') {
                        formatEnd = pattern.indexOf('}', formatStart);
                        if (formatEnd == -1) {
                            formatEnd = formatStart;
                        }
                    }
                    String dateFormat = "yyyy-MM-dd HH:mm:ss.SSS";
                    if (formatStart < pattern.length() && pattern.charAt(formatStart) == '{' && formatEnd > formatStart) {
                        dateFormat = pattern.substring(formatStart + 1, formatEnd);
                        i = formatEnd; // skip past format
                    }
                    sb.append(new java.text.SimpleDateFormat(dateFormat).format(new java.util.Date(event.getTimeStamp())));
                    break;
                case 'p': // level
                    sb.append(event.getLevel().toString());
                    break;
                case 'c': // logger name
                    sb.append(event.getLoggerName());
                    break;
                case 't': // thread name
                    sb.append(event.getThreadName());
                    break;
                case 'm': // message
                    sb.append(event.getMessage().getFormattedMessage());
                    break;
                case 'n': // newline
                    sb.append(System.lineSeparator());
                    break;
                case '-': // width modifier (ignored here)
                    // Skip the next character(s) until the conversion specifier
                    // Find the next conversion specifier (p, c, t, m, d, n)
                    int j = i + 2;
                    while (j < pattern.length() && !("pctmnd".contains(String.valueOf(pattern.charAt(j))))) {
                        j++;
                    }
                    if (j < pattern.length()) {
                        spec = pattern.charAt(j);
                        i = j - 1; // adjust i to new position
                        continue; // reprocess this spec
                    }
                    break;
                default:
                    sb.append('%').append(spec);
                    break;
            }
            i += 1; // skip specifier
        } else {
            sb.append(ch);
        }
        i += 1;
    }
    return sb.toString();
}

public String format(LoggingEvent event){
    String pattern = conversionPattern;
    if(pattern == null || pattern.isEmpty()){
        return event.getRenderedMessage();
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while(i < pattern.length()){
        char ch = pattern.charAt(i);
        if(ch == '%' && i+1 < pattern.length()){
            char next = pattern.charAt(i+1);
            switch(next){
                case 'd':{ // date
                    String dateFormat = "dd MMM yyyy HH:mm:ss,SSS";
                    int j = i+2;
                    if(j < pattern.length() && pattern.charAt(j) == '{'){
                        int end = pattern.indexOf('}', j+1);
                        if(end != -1){
                            dateFormat = pattern.substring(j+1, end);
                            j = end;
                        }
                    }
                    sb.append(new java.text.SimpleDateFormat(dateFormat).format(new java.util.Date(event.getTimeStamp())));
                    i = j+1;
                    break;
                }
                case 'p':{ // priority/level
                    sb.append(event.getLevel().toString());
                    i += 2;
                    break;
                }
                case 'c':{ // logger name
                    sb.append(event.getLoggerName());
                    i += 2;
                    break;
                }
                case 't':{ // thread name
                    sb.append(event.getThreadName());
                    i += 2;
                    break;
                }
                case 'm':{ // message
                    sb.append(event.getRenderedMessage());
                    i += 2;
                    break;
                }
                case 'n':{ // newline
                    sb.append(System.lineSeparator());
                    i += 2;
                    break;
                }
                case '%':{ // literal %
                    sb.append('%');
                    i += 2;
                    break;
                }
                default:{
                    sb.append('%').append(next);
                    i += 2;
                    break;
                }
            }
        } else {
            sb.append(ch);
            i++;
        }
    }
    return sb.toString();
}

public long contentLength() {
    // Attempt to retrieve the content length from the request headers
    if (request != null) {
        // Modern API: use getContentLengthLong() if available
        try {
            long len = request.getContentLengthLong();
            if (len >= 0) {
                return len;
            }
        } catch (NoSuchMethodError e) {
            // Fallback for older servlet API versions
            int legacyLen = request.getContentLength();
            if (legacyLen >= 0) {
                return legacyLen;
            }
        }

        // As a final resort, parse the "Content-Length" header manually
        String header = request.getHeader("Content-Length");
        if (header != null) {
            try {
                return Long.parseLong(header);
            } catch (NumberFormatException ignored) {
                // If parsing fails, ignore and return -1
            }
        }
    }
    return -1;
}

