private int parseEndOfLine(String headerPart, int end) {
    int len = headerPart.length();
    // Skip forward until we hit a CRLF sequence
    while (end < len - 1) {
        if (headerPart.charAt(end) == '\r' && headerPart.charAt(end + 1) == '\n') {
            // Return index of the CR (start of the sequence)
            return end;
        }
        end++;
    }
    // If the loop ends without finding CRLF, return the current end (may be len-1 or len)
    return end;
}

