    for (int i = end + 1; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i + 1; // index of the '\n' part of the CRLF
        }
    }
    return -1; // not found
}

