public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    // Create a mapping that maps each vertex to itself
    Map<V,V> vertexMapping = new HashMap<>();
    for (V v : graph.vertexSet()){
        vertexMapping.put(v, v);
    }
    // Create a mapping that maps each edge to itself
    Map<E,E> edgeMapping = new HashMap<>();
    for (E e : graph.edgeSet()){
        edgeMapping.put(e, e);
    }
    // Construct and return an identity isomorphism mapping
    return new IsomorphicGraphMapping<>(graph, graph, vertexMapping, edgeMapping);
}

