    return new IsomorphicGraphMapping<>(graph, graph);
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    // Collect all files and directories in a stack first
    Deque<File> stack = new ArrayDeque<>();
    List<File> all = new ArrayList<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File f = stack.pop();
        all.add(f);
        if (f.isDirectory()) {
            File[] children = f.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
    }
    // Register deleteOnExit in post‑order (files first, then directories)
    for (int i = all.size() - 1; i >= 0; i--) {
        all.get(i).deleteOnExit();
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

