public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null) {
            throw new IOException("Failed to list contents of directory: " + file);
        }
        for (File child : children) {
            forceDeleteOnExit(child);
        }
    }
    try {
        if (!file.deleteOnExit()) {
            throw new IOException("Could not schedule deletion of file: " + file);
        }
    } catch (SecurityException se) {
        throw new IOException("Security exception when scheduling deletion of file: " + file, se);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            java.util.Deque<File> stack = new java.util.ArrayDeque<>();
            stack.push(file);
            while (!stack.isEmpty()) {
                File curr = stack.pop();
                if (curr.isDirectory()) {
                    File[] children = curr.listFiles();
                    if (children != null) {
                        for (File child : children) {
                            stack.push(child);
                        }
                    }
                }
                if (!curr.delete()) {
                    // Deletion failed; ignore within shutdown hook
                }
            }
        } catch (Throwable t) {
            // Ignore any exception during shutdown
        }
    }));
}

