@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create two partitions of vertices for the bipartite graph
    V a1 = target.addVertex((V) "a1");
    V a2 = target.addVertex((V) "a2");
    V b1 = target.addVertex((V) "b1");
    V b2 = target.addVertex((V) "b2");

    // Connect every vertex in partition A with every vertex in partition B
    target.addEdge(a1, b1);
    target.addEdge(a1, b2);
    target.addEdge(a2, b1);
    target.addEdge(a2, b2);

    // Store created vertices in the result map
    resultMap.put("a1", a1);
    resultMap.put("a2", a2);
    resultMap.put("b1", b1);
    resultMap.put("b2", b2);
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Define labels for the two partitions of the bipartite graph
    String[] leftPartition = { "L1", "L2" };
    String[] rightPartition = { "R1", "R2" };

    // Add vertices for the left partition
    for (String label : leftPartition) {
        @SuppressWarnings("unchecked")
        V vertex = (V) label;
        target.addVertex(vertex);
        resultMap.put(label, vertex);
    }

    // Add vertices for the right partition
    for (String label : rightPartition) {
        @SuppressWarnings("unchecked")
        V vertex = (V) label;
        target.addVertex(vertex);
        resultMap.put(label, vertex);
    }

    // Add all possible edges between the two partitions (complete bipartite)
    for (String leftLabel : leftPartition) {
        V leftVertex = resultMap.get(leftLabel);
        for (String rightLabel : rightPartition) {
            V rightVertex = resultMap.get(rightLabel);
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

