public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    int sizeToWrite = size;
    // Write the length as a varint.
    while ((sizeToWrite & 0xFFFFFF80) != 0) {
        out.write((sizeToWrite & 0x7F) | 0x80);
        sizeToWrite >>>= 7;
    }
    out.write(sizeToWrite);
    // Serialize the message into the buffer.
    schema.write(message, buffer);
    // Flush buffer contents to the output stream.
    buffer.writeTo(out);
    // Reset the buffer so it can be reused.
    buffer.reset();
    return size;
}

