                    }
                } else {
                    System.out.println();
                }
            } catch (Exception e) {
                // If reflection fails, just print the throwable's toString()
                System.out.println();
                System.out.println(throwableInfoObj.toString());
            }
        } else {
            System.out.println();
        }
    } catch (Exception e) {
