public boolean equals(final byte[] data, int offset, final int len) {
    // The internal array is assumed to be stored in this.data
    byte[] internal = this.data;
    if (internal == null || data == null) {
        return internal == data; // true if both are null
    }
    // Length must match the requested length
    if (len != internal.length) {
        return false;
    }
    // Ensure the offset and length are within bounds of the input array
    if (offset < 0 || offset + len > data.length) {
        return false;
    }
    for (int i = 0; i < len; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

