    if (data == null || offset < 0 || len < 0 || offset + len > data.length) {
        return false;
    }

    // If the internal array is null, it can only match an empty segment
    if (buffer == null) {
        return len == 0;
    }

    // Length mismatch means arrays cannot be equal
    if (buffer.length != len) {
        return false;
    }

    // Compare byte by byte
