public void put(LoggingEvent o){
    int next = (tail + 1) % buffer.length;
    if(next == head){
        // The buffer is full – silently drop the event
        return;
    }
    buffer[tail] = o;
    tail = next;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();

    if (start >= end || FETCH_DATA_DURATION <= 0) {
        return ranges;
    }

    long current = start;
    while (current < end) {
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        if (next > current) {
            ranges.add(new TimeRange(current, next));
        }
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if(start >= end) {
        return ranges;
    }
    for(long current = start; current < end; current += FETCH_DATA_DURATION) {
        long rangeEnd = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, rangeEnd));
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    final long chunk = FETCH_DATA_DURATION;
    long current = start;
    while (current < end) {
        long next = Math.min(current + chunk, end);
        ranges.add(new TimeRange(current, next));
