static long compressTimeBucket(long timeBucket, int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day   = (int)(timeBucket % 100);
    // Compute the start day of the bucket that contains the original day
    int newDay = 1 + ((day - 1) / dayStep) * dayStep;
    // Make sure the new day does not exceed the real number of days in the month
    int monthLength = java.time.YearMonth.of(year, month).lengthOfMonth();
    if (newDay > monthLength) {
        newDay = monthLength;
    }
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 1) return timeBucket;
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day   = (int)(timeBucket % 100);
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    int daysInMonth;
    switch(month){
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31; break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30; break;
        case 2:
            daysInMonth = ((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0)) ? 29 : 28;
            break;
        default:
            daysInMonth = 30; break;
    }
    if(newDay > daysInMonth) newDay = daysInMonth;
    return year * 10000L + month * 100L + newDay;
}

