    }
    long year = timeBucket / 10000L;
    long month = (timeBucket / 100L) % 100L;
    long day = timeBucket % 100L;
    long compressedDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + compressedDay;
}

