public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException();
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        char c = str.charAt(i);
        if (Character.isHighSurrogate(c) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            int cp = Character.toCodePoint(c, str.charAt(i + 1));
            if (cp <= 0x7FF) {
                size += 2;
            } else if (cp <= 0xFFFF) {
                size += 3;
            } else {
                size += 4;
            }
            i += 2;
        } else {
            if (c <= 0x7F) {
                size += 1;
            } else if (c <= 0x7FF) {
                size += 2;
            } else {
                size += 3;
            }
            i++;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str == null || len <= 0) return 0;
    int end = Math.min(index + len, str.length());
    int count = 0;
    for(int i = index; i < end; i++){
        char ch = str.charAt(i);
        int codePoint;
        if(Character.isHighSurrogate(ch) && i + 1 < end){
            char low = str.charAt(i + 1);
            if(Character.isLowSurrogate(low)){
                codePoint = Character.toCodePoint(ch, low);
                i++; // skip low surrogate
            } else {
                // malformed surrogate pair, treat high surrogate as U+FFFD
                codePoint = 0xFFFD;
            }
        } else {
            codePoint = ch;
        }

        if(codePoint <= 0x7F){
            count += 1;
        } else if(codePoint <= 0x7FF){
            count += 2;
        } else if(codePoint <= 0xFFFF){
            count += 3;
        } else {
            count += 4;
        }
    }
    return count;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            utf8Size += 1;
        } else if (ch < 0x800) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                utf8Size += 4;
                i++; // skip the low surrogate
            } else {
                utf8Size += 3;
            }
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    if (end > str.length()) {
        end = str.length();
    }
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i++; // skip low surrogate
                } else {
                    // malformed surrogate pair, treat high surrogate as 3-byte
                    size += 3;
                }
            } else {
                // high surrogate at end of range, treat as 3-byte
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // low surrogate without preceding high surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int i = index;
    final int end = Math.min(index + len, str.length());
    int size = 0;
    while (i < end) {
        final char c = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(c) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            cp = Character.toCodePoint(c, str.charAt(i + 1));
            i += 2;
        } else {
            cp = c;
            i += 1;
        }
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

