    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present; this does not affect relative paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' while preserving empty trailing segments
    String[] rawSegments = path.split("/", -1);
    for (String rawSegment : rawSegments) {
        String seg = rawSegment;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(rawSegment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
