}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = path.startsWith("/") ? 1 : 0;
    int length = path.length();
    int i = start;
    while (i < length) {
        int nextSlash = path.indexOf('/', i);
        if (nextSlash == -1) {
            nextSlash = length;
        }
        String rawSegment = path.substring(i, nextSlash);
        if (!rawSegment.isEmpty()) {
            String decodedSegment = rawSegment;
            if (decode) {
                try {
                    decodedSegment = java.net.URLDecoder.decode(rawSegment, "UTF-8");
                } catch (Exception ignore) {
                }
            }
            segments.add(new PathSegmentImpl(rawSegment, decodedSegment));
        }
        i = nextSlash + 1;
        // skip any additional consecutive slashes
        while (i < length && path.charAt(i) == '/') {
            i++;
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = path.startsWith("/") ? 1 : 0;
    String remaining = path.substring(start);
    if (remaining.isEmpty()) {
        return segments;
    }
    String[] parts = remaining.split("/", -1); // keep trailing empty segments
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String raw = part;
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(raw, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported; fallback to raw
                decoded = raw;
            }
        }
        segments.add(new PathSegmentImpl(decoded));
    }
    return segments;
}

