    int total = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        out.write(cur.buf, 0, cur.count);
        total += cur.count;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the portion of the buffer that contains data.
        // It is assumed that `node.buf` holds the raw bytes and `node.pos`
        // indicates the number of valid bytes in that buffer.
        out.write(node.buf, 0, node.pos);
        totalSize += node.pos;
        node = node.next;
    }
    return totalSize;
}

