private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        int tag = type.getTag();              // JVMS verification_type_info tag
        stackMapTableEntries.writeByte(tag);
        if (tag == AbstractType.OBJECT) {
            // object type: tag + class index (u2)
            stackMapTableEntries.writeShort(type.getClassIndex());
        } else if (tag == AbstractType.UNINITIALIZED) {
            // uninitialized type: tag + offset (u2)
            stackMapTableEntries.writeShort(type.getOffset());
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        byte tag = type.getTag();
        switch (tag) {
            case 7: { // Object_variable_info
                int cpIndex = ((ObjectVariableInfo) type).getCpIndex();
                stackMapTableEntries.add(new byte[]{tag, (byte) (cpIndex >> 8), (byte) cpIndex});
                break;
            }
            case 8: { // Uninitialized_variable_info
                int offset = ((UninitializedVariableInfo) type).getOffset();
                stackMapTableEntries.add(new byte[]{tag, (byte) (offset >> 8), (byte) offset});
                break;
            }
            default: { // Top, Integer, Float, Long, Double, Null, UninitializedThis
                stackMapTableEntries.add(new byte[]{tag});
                break;
            }
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType at = currentFrame.get(i);
        int tag = at.getTag();
        stackMapTableEntries.writeByte(tag);
        if (tag == 7) { // ITEM_Object
            stackMapTableEntries.writeShort(at.getClassIndex());
        } else if (tag == 8) { // ITEM_Uninitialized
            stackMapTableEntries.writeShort(at.getOffset());
        }
    }
}

private void putAbstractTypes(final int start,final int end){
