        AbstractType type = currentFrame[i];
        stackMapTableEntries.putByte(type.getTag());
        switch(type.getTag()){
            case 7: // OBJECT
                stackMapTableEntries.putShort(type.getClassIndex());
                break;
            case 8: // UNINITIALIZED
                stackMapTableEntries.putShort(type.getOffset());
                break;
            default:
                // no extra data for other types
                break;
        }
    }
}

public void readFrom(final InputStream in) throws IOException {
    // Reset any existing state
    this.writePosition = 0;
    this.readPosition = 0;
    // Ensure we have a usable internal buffer
    if (this.buffer == null || this.buffer.length == 0) {
        this.buffer = new byte[8192];
    }
    int totalRead = 0;
    byte[] chunk = new byte[8192];
    int n;
    while ((n = in.read(chunk)) != -1) {
        // Resize the internal buffer if necessary
        if (totalRead + n > this.buffer.length) {
            int newCapacity = Math.max(this.buffer.length * 2, totalRead + n);
            byte[] newBuf = new byte[newCapacity];
            System.arraycopy(this.buffer, 0, newBuf, 0, totalRead);
            this.buffer = newBuf;
        }
        System.arraycopy(chunk, 0, this.buffer, totalRead, n);
        totalRead += n;
    }
    this.writePosition = totalRead;
}

public void readFrom(final InputStream in) throws IOException {
    final int CHUNK_SIZE = 8192;
    byte[] chunk = new byte[CHUNK_SIZE];
    java.io.ByteArrayOutputStream bufferStream = new java.io.ByteArrayOutputStream();
    int read;
    while ((read = in.read(chunk)) != -1) {
        bufferStream.write(chunk, 0, read);
    }
    byte[] data = bufferStream.toByteArray();
    this.buf = data;
    this.limit = data.length;
    this.pos = 0;
}

public void readFrom(final InputStream in) throws IOException {
    // Read all bytes from the input stream into a temporary byte array
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] temp = new byte[8192];
    int read;
    while ((read = in.read(temp)) != -1) {
        baos.write(temp, 0, read);
    }
    byte[] src = baos.toByteArray();

    // Ensure the internal buffer can hold the new data
    if (buffer == null || buffer.length < src.length) {
        buffer = new byte[src.length];
    }

    // Copy the data into the internal buffer and reset pointers
    System.arraycopy(src, 0, buffer, 0, src.length);
    length = src.length;
    pos = 0;
}

