@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() != 1) {
            throw new IllegalArgumentException("Cannot convert String of length " + s.length() + " to Character");
        }
        return new Character(s.charAt(0));
    }
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() != 1) {
            throw new IllegalArgumentException("Cannot convert CharSequence of length " + cs.length() + " to Character");
        }
        return new Character(cs.charAt(0));
    }
    if (value instanceof Number) {
        return new Character((char) ((Number) value).intValue());
    }
    throw new IllegalArgumentException("Cannot convert type " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Handle null values
    if (value == null) {
        return null;
    }

    // Check if the requested type is Character or primitive char
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        }

        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return Character.valueOf(str.charAt(0));
            }
            throw new IllegalArgumentException("Cannot convert String to Character: String length must be 1");
        }

        if (value instanceof Number) {
            // Convert number to char based on its int value
            int intVal = ((Number) value).intValue();
            return Character.valueOf((char) intVal);
        }

        // If value is of any other type, throw exception
        throw new IllegalArgumentException(
            "Cannot convert value of type " + value.getClass().getName() + " to Character");
    }

    // If the requested type is not supported by this converter, delegate or throw
    throw new IllegalArgumentException("Unsupported target type: " + type.getName());
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    boolean isCharTarget = type == char.class || Character.class.isAssignableFrom(type);
    if (!isCharTarget) {
        throw new IllegalArgumentException("Target type must be char or Character");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        }
        throw new IllegalArgumentException("String length must be 1 to convert to Character");
    }
    if (value instanceof Number) {
        int code = ((Number) value).intValue();
        if (Character.MIN_VALUE <= code && code <= Character.MAX_VALUE) {
            return (char) code;
        }
        throw new IllegalArgumentException("Numeric value out of character range");
    }
    String s = value.toString();
    if (s.length() == 1) {
        return s.charAt(0);
    }
    throw new IllegalArgumentException("Cannot convert value to Character: " + value);
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (!type.equals(Character.class) && !type.equals(char.class)) {
        throw new Exception("Target type is not Character: " + type.getName());
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert string \"" + str + "\" to Char: length must be 1");
        }
    }
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue;
    }
    if (value instanceof Boolean) {
        boolean b = (Boolean) value;
        return b ? '1' : '0';
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only support conversion to Character or primitive char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type);
    }

    if (value == null) {
        return null;
    }

    // If already a Character or primitive char (boxed)
    if (value instanceof Character) {
        return value;
    }

    // Handle Strings of length 1
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: " + str);
        }
    }

    // Handle CharSequence (e.g., StringBuilder)
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return Character.valueOf(cs.charAt(0));
        } else {
            throw new IllegalArgumentException("Cannot convert CharSequence to Character: " + cs);
        }
    }

    // Handle numeric types as Unicode code points
    if (value instanceof Number) {
        Number num = (Number) value;
        int intVal = num.intValue();
        return Character.valueOf((char) intVal);
    }

    // Handle Boolean: optional mapping
    if (value instanceof Boolean) {
        return Character.valueOf(((Boolean) value) ? '1' : '0');
    }

    // If all else fails, throw exception
    throw new IllegalArgumentException("Cannot convert value to Character: " + value);
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }
    String lowerStr = str.toLowerCase();
    // Build a set of all characters from the search strings in lower case
    Set<Character> charSet = new HashSet<>();
    for (String search : searchStrArray) {
        if (search == null) continue;
        String lowerSearch = search.toLowerCase();
        for (int i = 0; i < lowerSearch.length(); i++) {
            charSet.add(lowerSearch.charAt(i));
        }
    }
    for (int i = 0; i < lowerStr.length(); i++) {
        if (charSet.contains(lowerStr.charAt(i))) {
            return true;
        }
    }
    return false;
}

