private static boolean isPrime(int num) {
    if (num < 2) {
        return false;
    }
    if (num == 2 || num == 3) {
        return true;
    }
    if ((num & 1) == 0 || num % 3 == 0) {
        return false;
    }
    int r = (int) Math.sqrt(num);
    for (int f = 5; f <= r; f += 6) {
        if (num % f == 0 || num % (f + 2) == 0) {
            return false;
        }
    }
    return true;
}

