public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
            continue;
        }
        // Start of escape sequence
        i++;
        if (i >= len) {
            throw new IllegalArgumentException("Trailing backslash at end of string");
        }
        char esc = str.charAt(i);
        switch (esc) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                if (i + 4 >= len) {
                    throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                }
                String hex = str.substring(i + 1, i + 5);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence: " + hex, e);
                }
                i += 5; // move past 'u' and the four hex digits
                break;
            default:
                // Unknown escape: keep the character as is
                sb.append(esc);
                i++;
                break;
        }
    }
    return sb.toString();
}

