        if (value == null) {
            json.add(key, com.google.gson.JsonNull.INSTANCE);
        } else {
            json.addProperty(key, value);
        }
    }
    return json;
}

private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObjectBuilder builder = Json.createObjectBuilder();
    if (properties == null) {
        return builder.build();
    }
    for (KeyStringValuePair pair : properties) {
        if (pair == null || pair.getKey() == null) {
            continue;
        }
        Object value = pair.getValue();
        if (value == null) {
            builder.add(pair.getKey(), JsonValue.NULL);
        } else if (value instanceof String) {
            builder.add(pair.getKey(), (String) value);
        } else if (value instanceof Number) {
            if (value instanceof Integer) {
                builder.add(pair.getKey(), ((Integer) value).intValue());
            } else if (value instanceof Long) {
                builder.add(pair.getKey(), ((Long) value).longValue());
            } else if (value instanceof Double) {
                builder.add(pair.getKey(), ((Double) value).doubleValue());
            } else if (value instanceof Float) {
                builder.add(pair.getKey(), ((Float) value).floatValue());
            } else {
                builder.add(pair.getKey(), value.toString());
            }
        } else if (value instanceof Boolean) {
            builder.add(pair.getKey(), ((Boolean) value).booleanValue());
        } else {
            builder.add(pair.getKey(), value.toString());
        }
    }
    return builder.build();
}

protected int removeUnusedNodes() {
    if (children == null) {
        return 0;
    }
    int removedCount = 0;
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        removedCount += child.removeUnusedNodes();
        if (!child.isActive()) {
            it.remove();
            removedCount++;
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        java.util.List<Category> children = current.getChildren();
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                int count = 0;
                Deque<Category> subStack = new java.util.ArrayDeque<>();
                subStack.push(child);
                while (!subStack.isEmpty()) {
                    Category node = subStack.pop();
                    count++;
                    subStack.addAll(node.getChildren());
                }
                removed += count;
                it.remove();
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    // Handle root node separately; if root is inactive, delete the whole tree
    if (!root.isActive()) {
        root = null;
        return 1;
    }
    // Traverse root's children, removing inactive ones
    Iterator<CategoryNode> childIter = root.getSubcategories().iterator();
    while (childIter.hasNext()) {
        CategoryNode child = childIter.next();
        removed += removeUnusedRec(child, childIter);
    }
    return removed;
}

private int removeUnusedRec(CategoryNode node, Iterator<CategoryNode> parentIter) {
    if (node == null) {
        return 0;
    }
    int count = 0;
    if (!node.isActive()) {
        parentIter.remove();
        count = 1;
    } else {
        Iterator<CategoryNode> childIter = node.getSubcategories().iterator();
        while (childIter.hasNext()) {
            CategoryNode child = childIter.next();
            count += removeUnusedRec(child, childIter);
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    int removed = 0;
    if (children != null) {
        Iterator<Category> iterator = children.iterator();
        while (iterator.hasNext()) {
            Category child = iterator.next();
            if (child != null && !child.isActive()) {
                iterator.remove();
                removed++;
            } else if (child != null) {
                removed += child.removeUnusedNodes();
            }
        }
    }
    return removed;
}

protected int removeUnusedNodes() {
    // If the tree is empty, nothing to remove
    if (root == null) {
        return 0;
    }

    // If the root itself is inactive, remove the entire tree
    if (!root.isActive()) {
        int removedCount = countNodes(root);
        root = null;
        return removedCount;
    }

    // Recursively remove inactive subtrees
    return removeUnusedNodesFrom(root);
}

// Helper method that operates on a given node
private int removeUnusedNodesFrom(Category node) {
    int removed = 0;
    // Iterate over children with an iterator to safely remove elements
    Iterator<Category> it = node.getChildren().iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            // Remove the entire subtree of this inactive node
            removed += countNodes(child);
            it.remove(); // remove from parent’s children list
        } else {
            // Recursively process active subtrees
            removed += removeUnusedNodesFrom(child);
        }
    }
    return removed;
}

// Counts all nodes in a subtree (including the root of that subtree)
private int countNodes(Category node) {
    int count = 1; // count this node
    for (Category child : node.getChildren()) {
        count += countNodes(child);
    }
    return count;
}

