private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        return null;
    }

    // Create a circulator starting at the specified node and direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the starting node is the stop node, return immediately.
    if (circ.node().equals(stop)) {
        return circ;
    }

    // Traverse the outer face until we either find a node that satisfies the predicate
    // or we reach the stop node.
    while (!circ.node().equals(stop)) {
        if (predicate.test(circ.node())) {
            return circ;
        }
        circ = (dir >= 0) ? circ.next() : circ.prev();
    }

    // When the loop exits, circ is positioned at stop.
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator that starts at 'start', walks around the outer face in the given 'dir',
    // and stops automatically when it reaches the 'stop' node.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir, stop);

    // If the starting node is already the stop node, we are done.
    if (circ.node() == stop) {
        return circ;
    }

    // Walk the outer face until we either hit a node that satisfies the predicate
    // or reach the stop node.
    while (!circ.isAtStop()) {
        Node current = circ.node();
        if (predicate.test(current)) {
            break;
        }
        circ.next();
    }

    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    // If the start node itself satisfies the predicate, return a circulator pointing at it
    if (predicate.test(current)) {
        return new OuterFaceCirculator(current);
    }
    // Traverse along the outer face until we reach the stop node
    while (current != null && current != stop) {
        // Move to the next node in the specified direction (clockwise or counter‑clockwise)
        current = current.getOuterFaceNeighbour(dir);
        // If there is no further neighbour (e.g., reached an outlet), exit the loop to avoid NPE
        if (current == null) {
            break;
        }
        // If the new node matches the predicate, we found our target
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }
    // Either we reached the stop node or failed to find a matching node; return circulator to stop
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (true) {
        Node cur = circ.current();
        if (predicate.test(cur)) {
            return circ;
        }
        if (cur.equals(stop)) {
            return circ;
        }
        circ.move();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    Node current = start;
    // Traverse the outer face starting from 'start' in the specified direction.
    // Keep following the next edge/link until we either satisfy the predicate
    // or hit the stop node.  If the predicate never matches, return a
    // circulator positioned at the stop node.
    while (current != null && !current.equals(stop)) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        // Assume Node exposes a method to get the next node on the outer face
        // in the given direction.  If such a method does not exist, the caller
        // must provide a suitable replacement.
        current = current.nextOnOuterFace(dir);
    }
    // Either we reached the stop node or the face was empty; return a
    // circulator to stop (the caller will handle the case where stop is null).
    return new OuterFaceCirculator(stop);
}

