    java.util.Map<String, String> captures = new java.util.LinkedHashMap<>();
    int groupIndex = 1;
    while (varMatcher.find()) {
        String varName = varMatcher.group(1);
        String value = matcher.group(groupIndex++);
        captures.put(varName, value);
    }

    // Create and return a MatchResult instance
    return new MatchResult(captures, uri.toString());
}

