    // Suspend the resource unless it is a WebSocket transport
    String transport = r.getTransport();
    if (transport == null || !transport.equalsIgnoreCase("websocket")) {
        // Default suspend without timeout
        try {
            r.suspend();
        } catch (Throwable t) {
            // ignore any exception that may occur during suspend
        }
    }
    return Action.CONTINUE;
}

