    if (AtmosphereResource.TRANSPORT_WEBSOCKET.equals(transport)
            || AtmosphereResource.TRANSPORT_SSE.equals(transport)
            || AtmosphereResource.TRANSPORT_STREAM.equals(transport)) {
        // Continuous transports: suspend without a timeout
        r.suspend();
    } else {
        // Other transports: suspend with the default settings
        r.suspend();
    }
