public byte[] toByteArray(){
    // If the source is already a byte array, simply return it or a copy.
    if (data != null) {
        return data.clone();
    }
    // If the source is an InputStream, read it into a byte array.
    if (inputStream != null) {
        try {
            java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int read;
            while ((read = inputStream.read(buf)) != -1) {
                baos.write(buf, 0, read);
            }
            return baos.toByteArray();
        } catch (java.io.IOException e) {
            throw new RuntimeException(e);
        }
    }
    // Fallback: return an empty array if neither is available.
    return new byte[0];
}

