protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour==null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map: vertex -> set of incident edges in the tour
    Map<V, Set<E>> adjacency = new HashMap<>();
    for(E e : tour){
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k->new HashSet<>()).add(e);
        adjacency.computeIfAbsent(target, k->new HashSet<>()).add(e);
    }

    // Pick arbitrary starting vertex
    E startEdge = tour.iterator().next();
    V current = graph.getEdgeSource(startEdge);
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();

    Set<E> used = new HashSet<>();
    vertexList.add(current);

    while(!used.size()==tour.size()){
        Set<E> incident = adjacency.get(current);
        if(incident==null){
            break;
        }
        E nextEdge = null;
        for(E e : incident){
            if(!used.contains(e)){
                nextEdge = e;
                break;
            }
        }
        if(nextEdge==null){
            break; // dead end
        }
        edgeList.add(nextEdge);
        used.add(nextEdge);
        // Remove the edge from adjacency of both vertices
        V opp = graph.getEdgeSource(nextEdge).equals(current) ?
                graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        adjacency.get(current).remove(nextEdge);
        adjacency.get(opp).remove(nextEdge);

        current = opp;
        vertexList.add(current);
    }

    if(edgeList.isEmpty()){
        return null;
    }

    return new DefaultGraphPath<>(graph, vertexList, edgeList, 0, vertexList.size()-1);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Return an empty path if the set is null or empty
    if (tour == null || tour.isEmpty()) {
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }

    // Prepare containers for the result
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    double weight = 0.0;

    // Map each vertex to the set of incident edges contained in the tour
    Map<V, Set<E>> vertexToEdges = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        vertexToEdges.computeIfAbsent(u, k -> new HashSet<>()).add(e);
        vertexToEdges.computeIfAbsent(v, k -> new HashSet<>()).add(e);
    }

    // Pick an arbitrary start vertex (the source of the first edge)
    Iterator<E> edgeIt = tour.iterator();
    E firstEdge = edgeIt.next();
    V current = graph.getEdgeSource(firstEdge);
    vertices.add(current);

    // Keep track of which edges have already been used
    Set<E> used = new HashSet<>();

    // Walk through the tour until we have processed all edges
    while (used.size() < tour.size()) {
        Set<E> incident = vertexToEdges.getOrDefault(current, Collections.emptySet());
        E nextEdge = null;
        for (E e : incident) {
            if (!used.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            // No unused edge found, break to avoid infinite loop
            break;
        }

        // Record the edge
        edges.add(nextEdge);
        used.add(nextEdge);
        weight += graph.getEdgeWeight(nextEdge);

        // Determine the next vertex
        V u = graph.getEdgeSource(nextEdge);
        V v = graph.getEdgeTarget(nextEdge);
        current = u.equals(current) ? v : u;

        vertices.add(current);
    }

    // Build and return the path
    return new GraphPathImpl<>(graph, vertices, edges, weight);
}

