protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Collect all vertices involved in the set of edges
    Set<V> vertices = new HashSet<>();
    for (E e : tour) {
        vertices.add(graph.getEdgeSource(e));
        vertices.add(graph.getEdgeTarget(e));
    }

    // Try to find a vertex of degree 1 to start the tour (path case)
    V start = null;
    for (V v : vertices) {
        int degree = 0;
        for (E e : tour) {
            if (v.equals(graph.getEdgeSource(e)) || v.equals(graph.getEdgeTarget(e))) {
                degree++;
            }
        }
        if (degree == 1) {
            start = v;
            break;
        }
    }

    // If no vertex of degree 1, take an arbitrary vertex (cycle case)
    if (start == null) {
        E first = tour.iterator().next();
        start = graph.getEdgeSource(first);
    }

    // Build adjacency map: vertex -> list of incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V w = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(w, k -> new ArrayList<>()).add(e);
    }

    // Order the edges to form the tour/path
    List<E> ordered = new ArrayList<>(tour.size());
    V current = start;
    V previous = null;
    while (ordered.size() < tour.size()) {
        List<E> edges = adjacency.get(current);
        if (edges == null) {
            break;
        }
        E chosen = null;
        for (E e : edges) {
            V other = graph.getEdgeSource(e).equals(current) ?
                    graph.getEdgeTarget(e) : graph.getEdgeSource(e);
            if (!other.equals(previous)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) {
            break;
        }
        ordered.add(chosen);
        V next = graph.getEdgeSource(chosen).equals(current) ?
                graph.getEdgeTarget(chosen) : graph.getEdgeSource(chosen);
        previous = current;
        current = next;
    }

    V end = current;
    return new org.jgrapht.graph.SimpleGraphPath<>(graph, start, end, ordered);
}

