private Class findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className may not be null");
    }
    // Try the thread context classloader first, then fallback to the class's loader
    ClassLoader cl = Thread.currentThread().getContextClassLoader();
    try {
        return Class.forName(className, true, cl);
    } catch (ClassNotFoundException e) {
        // Fallback to the class loader that loaded this class
        return Class.forName(className, true, this.getClass().getClassLoader());
