        throw new IllegalArgumentException(
            "The new column name '" + newName + "' is already in use");
    }
    // Remove the old entry and insert the new one while preserving the storage-level name.
    String storageName = nameMap.remove(oldName);
    nameMap.put(newName, storageName);
}

