    // Get the neighboring nodes
    ListNodeImpl<E> prev = node.getPrev();
    ListNodeImpl<E> next = node.getNext();

    // Detach the node from its neighbors
    if (prev != null) {
        prev.setNext(next);
    } else {
        // node is the head
        head = next;
    }

    if (next != null) {
        next.setPrev(prev);
    } else {
        // node is the tail
        tail = prev;
    }

    // Help garbage collection
    node.setPrev(null);
    node.setNext(null);
    if (node instanceof MutableElementHolder) {
        ((MutableElementHolder) node).setElement(null);
    }

    size--;
    return true;
}

public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> ranges = new ArrayList<>();
    // If there are no current profiles, return an empty list immediately
    if (currentProfiles == null || currentProfiles.isEmpty()) {
        return ranges;
    }
    // Iterate over each profile to build its corresponding sequence range
    for (Profile profile : currentProfiles) {
        // Retrieve the segment snapshot for the current profile
        SegmentSnapshot snapshot = segmentSnapshots.get(profile.getId());
        if (snapshot == null) {
            // Skip this profile if no snapshot is available
            continue;
        }
        // Obtain the list of search sequences for this profile
        List<SearchSequence> sequences = searchSequenceRepository.getByProfile(profile.getId());
        if (sequences == null || sequences.isEmpty()) {
            // Skip if there are no search sequences
            continue;
        }
        // Determine the start and end indices from the first and last search sequence
        int startIndex = sequences.get(0).getIndex();
        int endIndex = sequences.get(sequences.size() - 1).getIndex();
        // Create a new SequenceRange and add it to the collection
        SequenceRange range = new SequenceRange(startIndex, endIndex);
        ranges.add(range);
    }
    // Optional: sort the ranges by start index for deterministic ordering
    ranges.sort(Comparator.comparingInt(SequenceRange::getStart));
    return ranges;
}

