    return new java.util.ArrayList<>();
}

public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> ranges = new ArrayList<>();
    for (SegmentSnapshot ss : segmentSnapshots){
        ranges.add(new SequenceRange(ss.getStartIndex(), ss.getEndIndex()));
    }
    return ranges;
}

public List<SequenceRange> buildSequenceRanges(){
    java.util.List<Segment> currentSegments = profileRepository.getCurrentProfileSegments();
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    for (Segment seg : currentSegments) {
        ranges.add(new SequenceRange(seg.getStart(), seg.getEnd()));
    }
    java.util.Collections.sort(ranges, java.util.Comparator.comparingLong(SequenceRange::getStart));
    return ranges;
}

