public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    // Handle both forward and backward slashes to support different OS
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int dot = path.lastIndexOf('.');
    // No '.' after the last slash, or dot at start (hidden file), or dot is last character
    if (dot <= lastSlash || dot == 0 || dot == path.length() - 1) {
        return null;
    }
    return path.substring(0, dot);
}

