private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int n = bounds.size();
    long total = 0L;
    long[] suffix = new long[n];
    for (int i = 0; i < n; i++) {
        total += bounds.get(i);
    }
    long acc = 0L;
    for (int i = n - 1; i >= 0; i--) {
        acc += bounds.get(i);
        suffix[i] = acc;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffixList.add((int) suffix[i]); // cast to int as per method signature
    }
    return new Pair<>(suffixList, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(Collections.emptyList(), 0L);
    }
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long total = 0L;
    for (int value : bounds) {
        total += value;
    }
    long suffix = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffix += bounds.get(i);
        suffixSum.add(0, (int) suffix);
    }
    return new Pair<>(suffixSum, total);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    if (n == 0) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int[] suffixArray = new int[n];
    long totalSum = 0L;
    int acc = 0;
    for (int i = n - 1; i >= 0; i--) {
        acc += bounds.get(i);
        suffixArray[i] = acc;
        totalSum += bounds.get(i);
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int val : suffixArray) {
        suffixList.add(val);
    }
    return new Pair<>(suffixList, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffix = new ArrayList<>();
    long total = 0L;
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(suffix, total);
    }
    for (int i = bounds.size() - 1; i >= 0; i--) {
        total += bounds.get(i);
        // add to the front to preserve suffix order
        suffix.add(0, (int) total);
    }
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long total = 0;
    long running = 0;
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(suffixSum, total);
    }
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int val = bounds.get(i);
        running += val;
        suffixSum.add(running); // adding at end will produce reversed order
        total += val;
    }
    // reverse suffixSum to match original order
    Collections.reverse(suffixSum);
    return new Pair<>(suffixSum, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        return;
    }
    if (from < 0) {
        from = 0;
    }
    if (to >= arr.length) {
        to = arr.length - 1;
    }
    if (from > to) {
        return;
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

