private void moveAllListNodes(DoublyLinkedList<E> list) {
    // return if the input list is null or empty
    if (list == null || list.isEmpty()) {
        return;
    }

    // Link the two lists together
    if (this.isEmpty()) {
        // If this list is empty, just take over the entire other list
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Append the other list after this list’s tail
        this.tail.setNext(list.head);
        list.head.setPrev(this.tail);
        this.tail = list.tail;
    }

    // Update the size
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }
    // Iterate through the source list, removing each node and adding it to this list.
    ListNodeImpl<E> node = list.getFirst();
    while (node != null) {
        // Remember the next node before unlinking the current one.
        ListNodeImpl<E> next = node.getNext();
        // Atomically remove from the source list.
        list.removeListNode(node);
        // Atomically add to this list.
        this.addListNode(node);
        // Advance to the next node that was captured before removal.
        node = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list == this || list.head == null) {
        return;
    }
    final int thisHash = System.identityHashCode(this);
    final int otherHash = System.identityHashCode(list);
    if (thisHash < otherHash) {
        synchronized (this) {
            synchronized (list) {
                ListNodeImpl<E> node;
                while ((node = list.head) != null) {
                    list.removeListNode(node);
                    this.addListNode(node);
                }
            }
        }
    } else if (thisHash > otherHash) {
        synchronized (list) {
            synchronized (this) {
                ListNodeImpl<E> node;
                while ((node = list.head) != null) {
                    list.removeListNode(node);
                    this.addListNode(node);
                }
            }
        }
    } else {
        synchronized (this) {
            synchronized (list) {
                ListNodeImpl<E> node;
                while ((node = list.head) != null) {
                    list.removeListNode(node);
                    this.addListNode(node);
                }
            }
        }
    }
}

