        return;
    }
    if (this == list) {
        return; // nothing to do
    }
    if (this.size == 0) {
        this.firstNode = list.firstNode;
        this.lastNode = list.lastNode;
    } else {
        this.lastNode.next = list.firstNode;
        list.firstNode.prev = this.lastNode;
        this.lastNode = list.lastNode;
    }
    this.size += list.size;
    // clear the source list
    list.firstNode = null;
    list.lastNode = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is null or empty, nothing to move.
    if (list == null || list.size == 0) {
        return;
    }

    // If this list is empty, simply adopt the source list's nodes.
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Otherwise splice the source list at the end of this list.
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update the element count for this list.
    this.size += list.size;

    // Clear the source list so that it becomes empty.
    list.head = null;
    list.tail = null;
    list.size = 0;

    // Update modification counts if present.
    this.modCount += list.modCount;
    list.modCount = 0;
}

