    for (PropertyDescriptor pd : srcDescs) {
        // Only consider properties that are readable and writable in the source map
        if (pd.getReadMethod() != null && pd.getWriteMethod() != null) {
            Object value = map.get(pd.getName());
            try {
                this.put(pd.getName(), value);
            } catch (IllegalArgumentException e) {
                // Target property is not writable or doesn't exist; ignore it
            }
        }
    }
}

