    // Clear any previous selection and select the requested row
    table.clearSelection();
    table.setRowSelectionInterval(row, row);
    table.setColumnSelectionInterval(0, 0); // keep column in focus

    // Ensure the selected row is visible in the viewport and repaint after scrolling
    SwingUtilities.invokeLater(() -> {
        Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            pane.getViewport().scrollRectToVisible(cellRect);
        }
        // Delay repaint slightly to allow the scroll operation to complete
        javax.swing.Timer repaintTimer = new javax.swing.Timer(50, e -> {
            table.repaint();
            ((javax.swing.Timer) e.getSource()).stop();
        });
        repaintTimer.setRepeats(false);
        repaintTimer.start();
    });
}

