        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, data.length);
        data = newData;
    }
    data[pos]     = (byte)(intValue >>> 24);
    data[pos + 1] = (byte)(intValue >>> 16);
    data[pos + 2] = (byte)(intValue >>> 8);
    data[pos + 3] = (byte)intValue;
