    final int newPos = this.i + 4;
    this.i = newPos;
    if (newPos > this.n) {
        this.n = newPos;
        if (this.i >= buf.length) {
            final byte[] newBuf = new byte[Math.max(this.i << 1, buf.length + 1)];
            System.arraycopy(buf, 0, newBuf, 0, buf.length);
            this.b = newBuf;
        }
    }
    buf[this.i - 4] = (byte)(intValue >>> 24);
    buf[this.i - 3] = (byte)(intValue >>> 16);
    buf[this.i - 2] = (byte)(intValue >>> 8);
    buf[this.i - 1] = (byte)(intValue);
    return this;
}

