public void abbreviate(final int nameStart, final StringBuffer buf){
    if (name == null || buf == null || nameStart >= name.length() || nameStart < 0) {
        return; // nothing to abbreviate
    }
    int len = name.length();
    for (int i = nameStart; i < len; ) {
        // Skip any non‑alphanumeric separator characters
        while (i < len && !Character.isLetterOrDigit(name.charAt(i))) {
            i++;
        }
        if (i >= len) {
            break;
        }
        // Append the first character of the next word in upper case
        buf.append(Character.toUpperCase(name.charAt(i)));
        // Advance i to the end of this word
        i++;
        while (i < len && Character.isLetterOrDigit(name.charAt(i))) {
            i++;
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (nameStart < 0 || nameStart >= buf.length()) return;
    String fullName = buf.substring(nameStart);
    String[] parts = fullName.split("\\.");
    StringBuilder abbr = new StringBuilder();
    if (parts.length > 0) {
        for (int i = 0; i < parts.length - 1; i++) {
            if (!parts[i].isEmpty()) {
                abbr.append(parts[i].charAt(0)).append(".");
            }
        }
        abbr.append(parts[parts.length - 1]);
    }
    buf.replace(nameStart, buf.length(), abbr.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Ensure we have a valid start position.
    if (nameStart < 0 || nameStart >= fullName.length()) {
        return;
    }

    boolean startOfPart = true;
    for (int i = nameStart; i < fullName.length(); i++) {
        char c = fullName.charAt(i);

        // Append the first character of each part (letters or digits).
        if (startOfPart && Character.isLetterOrDigit(c)) {
            buf.append(c);
            startOfPart = false;
        }

        // Consider '.' 'un' '_' '-' as delimiters.
        if (c == '.' || c == '_' || c == '-') {
            startOfPart = true;
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds != null && bounds.length > 0) {
        Type first = bounds[0];
        if (first != null) {
            return first;
        }
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    for (Type bound : bounds) {
        if (bound instanceof Class || bound instanceof ParameterizedType
                || bound instanceof WildcardType) {
            return bound;
        }
        if (bound instanceof TypeVariable) {
            Type resolved = resolveBound((TypeVariable<?>) bound);
            if (resolved != Unknown.class) {
                return resolved;
            }
        }
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Retrieve all bounds declared for the type variable
    Type[] bounds = typeVariable.getBounds();
    // Iterate over each bound
    for (Type bound : bounds) {
        // If the bound is a class and not the default Object, return it
        if (bound instanceof Class<?> cls && !cls.equals(Object.class)) {
            return cls;
        }
    }
    // If none of the bounds can be resolved, fallback to Unknown.class
    return Unknown.class;
}

