private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A set with 0 or 1 vertices is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Iterate over all unordered pairs of distinct vertices
    for (V v : vertices) {
        for (V u : vertices) {
            if (v.equals(u)) {
                continue; // skip the same vertex
            }
            // In an undirected graph we would only need to check one direction.
            // For a directed graph, a clique generally requires an edge in both directions.
            // Here we assume a simple edge check suffices for the intended usage.
            if (graph.getEdge(v, u) == null) {
                return false;
            }
        }
    }

    return true;
}

