            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        int bestIndex = -1;
        for (int j = 0; j < keys.size(); j++) {
            if (i == j) continue;
            K keyI = keys.get(i);
            K keyJ = keys.get(j);
            if (keyI instanceof Comparable<? super Object> && keyJ instanceof Comparable<? super Object>) {
                @SuppressWarnings("unchecked")
                Comparable<Object> compI = (Comparable<Object>) keyI;
                @SuppressWarnings("unchecked")
                Comparable<Object> compJ = (Comparable<Object>) keyJ;
                if (compJ.compareTo(compI) < 0) {
                    if (bestIndex == -1) {
                        bestIndex = j;
                    } else {
                        K bestKey = keys.get(bestIndex);
                        if (bestKey instanceof Comparable<? super Object>) {
                            @SuppressWarnings("unchecked")
                            Comparable<Object> compBest = (Comparable<Object>) bestKey;
                            if (compJ.compareTo(compBest) > 0) {
                                bestIndex = j;
                            }
                        }
                    }
                }
            }
        }
        bounds.add(bestIndex);
    }
    return bounds;
}

