        if (key instanceof Integer) {
            int current = (Integer) key;
            for (K other : keys) {
                if (other instanceof Integer) {
                    int candidate = (Integer) other;
                    if (candidate < current && candidate > maxLower) {
                        maxLower = candidate;
                    }
                }
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

