private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return bounds;
    }
    // Use a TreeSet to have keys sorted
    NavigableSet<K> sorted = new TreeSet<>(keys);
    for (K key : keys){
        K higher = sorted.higher(key);
        if (higher == null){
            bounds.add(Integer.MAX_VALUE);
        } else {
            try {
                bounds.add(((Integer) higher).intValue());
            } catch (ClassCastException e){
                bounds.add(higher.hashCode());
            }
        }
    }
    return bounds;
}

