private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    List<Integer> numericKeys = new ArrayList<>(keys.size());
    for (K k : keys) {
        if (k == null) {
            numericKeys.add(Integer.MIN_VALUE);
        } else if (k instanceof Number) {
            numericKeys.add(((Number) k).intValue());
        } else {
            numericKeys.add(k.hashCode());
        }
    }
    for (int i = 0; i < numericKeys.size(); i++) {
        int val = numericKeys.get(i);
        int bound = Integer.MAX_VALUE;
        for (int j = 0; j < numericKeys.size(); j++) {
            if (i == j) continue;
            int candidate = numericKeys.get(j);
            if (candidate > val && candidate < bound) {
                bound = candidate;
            }
        }
        upperBounds.add(bound == Integer.MAX_VALUE ? Integer.MAX_VALUE : bound);
    }
    return upperBounds;
}

