    String message = layout.format(event);
    // Append a line separator so each log entry appears on a new line in the client output
    String record = message + System.lineSeparator();
    byte[] data = record.getBytes(java.nio.charset.StandardCharsets.UTF_8);

    // Synchronize on the client list/ set to avoid concurrent modifications while iterating
    synchronized (clients) {
        java.util.Iterator<java.net.Socket> it = clients.iterator();
